chrome.runtime.onInstalled.addListener(()=>{console.log("[CampusApply] 插件已安装/更新"),chrome.contextMenus.create({id:"campus-apply-fill-field",title:"🤖 智能填充此字段",contexts:["editable"]}),chrome.contextMenus.create({id:"campus-apply-fill-page",title:"📋 一键填充整页",contexts:["page"]})});chrome.contextMenus.onClicked.addListener((e,a)=>{a!=null&&a.id&&(e.menuItemId==="campus-apply-fill-field"?chrome.tabs.sendMessage(a.id,{type:"FILL_SINGLE_FIELD"}):e.menuItemId==="campus-apply-fill-page"&&chrome.tabs.sendMessage(a.id,{type:"FILL_ALL_FIELDS"}))});chrome.runtime.onMessage.addListener((e,a,r)=>{switch(e.type){case"OPEN_SIDEBAR":{const t=e.tabId;if(!t){r({success:!1,error:"缺少 tabId，无法打开侧边栏"});break}return chrome.sidePanel.setOptions({tabId:t,path:"src/sidebar/index.html",enabled:!0}),chrome.sidePanel.open({tabId:t}).then(()=>r({success:!0})).catch(c=>{const s=c instanceof Error?c.message:String(c);console.warn("[CampusApply] 打开侧边栏失败:",s),r({success:!1,error:s})}),!0}case"GET_ACTIVE_TAB":return chrome.tabs.query({active:!0,currentWindow:!0},t=>{r({tab:t[0]})}),!0;case"SCAN_PAGE":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"SCAN_FORM_FIELDS"},t=>{r(t)}),!0;break;case"FILL_FIELDS":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"EXECUTE_FILL",data:e.data},t=>{r(t)}),!0;break;case"CLEAR_FILLED":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"CLEAR_ALL_FILLED"},t=>{r(t)}),!0;break;case"TRIGGER_FILL_FROM_CONTEXT_MENU":chrome.runtime.sendMessage({type:"AUTO_FILL"}).catch(()=>{}),r({success:!0});break}});
